package com.spendwise.transaction;
import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.Map;
@RestController @RequestMapping("/api/summary") public class SummaryController { private final TransactionRepository repository; public SummaryController(TransactionRepository repository){this.repository=repository;} @GetMapping public Map<String,BigDecimal> summary(@RequestParam String month){LocalDate start;try{start=LocalDate.parse(month+"-01");}catch(RuntimeException e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Month must use yyyy-MM format");}var rows=repository.findAllByDateBetweenOrderByDateDesc(start,start.withDayOfMonth(start.lengthOfMonth()));BigDecimal income=rows.stream().filter(t->t.getType()==TransactionType.INCOME).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal expense=rows.stream().filter(t->t.getType()==TransactionType.EXPENSE).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("income",income,"expense",expense,"balance",income.subtract(expense));} }
